// Generated by `just generate` from `src/plugins/dotclaude/slices/guard/domain/reason.ts`. Edit the source and run `just generate`.
// The deny text of the `guard` slice. It is the only place where the text of a deny is.
// The text holds the exact denied command, in a fenced block, so that the reader can run it or report it.
// A message to Claude gives the reason and the next step, in plain words.

import type { Tier } from "./matchers/types.ts";

/** What a deny needs: the tier of the matcher, the denied command, and whether the caller is a subagent. */
export type DenyInput = { tier: Tier; command: string; subagent: boolean };

/** The command in a fenced block, so that its spaces and quotes stay as they are. */
const quoted = (command: string): string => ["```", command, "```"].join("\n");

/** The deny text of a matcher of `tier` for `command`. */
export const denyReason = ({ tier, command, subagent }: DenyInput): string => {
  if (tier === "subagent")
    return [
      "dotclaude forbids this command in a subagent, because it changes the checkout that other workers share.",
      "Do this work in your own worktree instead.",
      "The denied command:",
      quoted(command),
    ].join("\n");
  if (subagent)
    return [
      "dotclaude forbids this destructive action.",
      "Stop this work.",
      "Put this exact command in your report, so that the main session can give it to the user:",
      quoted(command),
    ].join("\n");
  return [
    "dotclaude forbids this destructive action.",
    "Do not try another way to do it.",
    "Stop this work.",
    "Ask the user to run this exact command as a `!` command, then wait for the user:",
    quoted(command),
  ].join("\n");
};
